use ultragraphdb_common_utils::go_utf8;

use crate::tables::segment_tables::{
    S_EOF_TRANS, S_FIRST_FINAL, S_INDEX_OFFSETS, S_INDICIES, S_KEY_OFFSETS, S_RANGE_LENGTHS,
    S_SINGLE_LENGTHS, S_START, S_TRANS_ACTIONS, S_TRANS_KEYS, S_TRANS_TARGS,
};
use crate::types::segment_type::SegmentType;

/// segment's `ParseError` text.
pub(crate) const PARSE_ERROR: &str = "unicode word segmentation parse error";

/// The first segment `segmentWords` finds: its bytes as a range of the input, its type, and how far it advances.
struct Found {
    start: usize,
    end: usize,
    advance: usize,
    typ: SegmentType,
}

/// What a scanner action decided about the token it matched.
enum Finish {
    Number,
    Word,
    Hangul,
    Ideo,
    None,
}

enum Label {
    Resume,
    EofTrans(usize),
    Again,
    TestEof,
}

/// The segments of `input` as blevesearch/segment's direct `Segmenter` returns them, each as its offset in `input`,
/// its length and its type, and the error it stopped on.
///
/// Each step runs `SegmentWords(data, atEOF = true)` on the rest of the input, which returns the first segment
/// only. A step that finds no segment ends the segmentation without an error: segment does so when a Hangul,
/// Han, Hiragana, Katakana or non-word segment is followed by an invalid UTF-8 byte, and the rest of the input is
/// then dropped.
pub(crate) fn word_segments(
    input: &[u8],
) -> (Vec<(usize, usize, SegmentType)>, Option<&'static str>) {
    let mut out = Vec::new();
    let mut start = 0;
    while start < input.len() {
        match segment_words(&input[start..]) {
            Err(e) => return (out, Some(e)),
            Ok(None) => break,
            Ok(Some(f)) => {
                out.push((start + f.start, f.end - f.start, f.typ));
                start += f.advance;
            }
        }
    }
    (out, None)
}

/// segment's `segmentWords(data, 1, true, nil, nil)`: the first segment of `data`.
fn segment_words(data: &[u8]) -> Result<Option<Found>, &'static str> {
    let pe = data.len() as isize;
    let eof = pe;
    let mut cs = S_START;
    let mut p: isize = 0;
    let mut act = 0;
    let mut start_pos: isize = 0;
    let mut end_pos: isize = 0;

    let mut label = if p == pe {
        Label::TestEof
    } else {
        Label::Resume
    };
    loop {
        match label {
            Label::Resume => {
                let c = data[p as usize];
                let mut keys = S_KEY_OFFSETS[cs] as isize;
                let mut trans = S_INDEX_OFFSETS[cs] as isize;
                let mut matched = false;

                let klen = S_SINGLE_LENGTHS[cs] as isize;
                if klen > 0 {
                    let mut lower = keys;
                    let mut upper = keys + klen - 1;
                    while upper >= lower {
                        let mid = lower + ((upper - lower) >> 1);
                        let k = S_TRANS_KEYS[mid as usize];
                        if c < k {
                            upper = mid - 1;
                        } else if c > k {
                            lower = mid + 1;
                        } else {
                            trans += mid - keys;
                            matched = true;
                            break;
                        }
                    }
                    if !matched {
                        keys += klen;
                        trans += klen;
                    }
                }
                if !matched {
                    let klen = S_RANGE_LENGTHS[cs] as isize;
                    if klen > 0 {
                        let mut lower = keys;
                        let mut upper = keys + (klen << 1) - 2;
                        while upper >= lower {
                            let mid = lower + (((upper - lower) >> 1) & !1);
                            if c < S_TRANS_KEYS[mid as usize] {
                                upper = mid - 2;
                            } else if c > S_TRANS_KEYS[mid as usize + 1] {
                                lower = mid + 2;
                            } else {
                                trans += (mid - keys) >> 1;
                                matched = true;
                                break;
                            }
                        }
                    }
                    if !matched {
                        trans += klen;
                    }
                }
                label = Label::EofTrans(S_INDICIES[trans as usize] as usize);
            }
            Label::EofTrans(trans) => {
                cs = S_TRANS_TARGS[trans] as usize;
                // The generated actions also keep the scanner's token end (te) and move p back to it before a
                // finish action; every finish action returns here, as one token is wanted and atEOF is set, so
                // those registers are never read again and are left out.
                let finish = match S_TRANS_ACTIONS[trans] {
                    0 => None,
                    10 | 18 => {
                        end_pos = p;
                        None
                    }
                    34 | 4 => Some(Finish::Number),
                    37 | 12 => Some(Finish::Hangul),
                    35 | 7 => Some(Finish::Word),
                    39 | 38 | 40 | 17 | 15 | 19 => Some(Finish::Ideo),
                    41 | 32 | 36 | 31 | 21 | 8 | 1 => Some(Finish::None),
                    3 => match act {
                        1 => Some(Finish::Number),
                        2 => Some(Finish::Hangul),
                        3 | 5 => Some(Finish::Ideo),
                        4 => Some(Finish::Word),
                        7 | 12 | 13 => Some(Finish::None),
                        _ => None,
                    },
                    28 => {
                        start_pos = p;
                        end_pos = p;
                        None
                    }
                    33 | 13 => {
                        end_pos = p;
                        Some(Finish::None)
                    }
                    26 | 27 => {
                        start_pos = p;
                        end_pos = p;
                        Some(Finish::None)
                    }
                    a @ (5 | 11 | 16 | 6 | 14 | 20 | 9 | 2) => {
                        end_pos = p;
                        act = match a {
                            5 => 1,
                            11 => 2,
                            16 => 3,
                            6 => 4,
                            14 => 5,
                            20 => 7,
                            9 => 12,
                            _ => 13,
                        };
                        None
                    }
                    a @ (29 | 30 | 25) => {
                        start_pos = p;
                        end_pos = p;
                        act = match a {
                            29 => 1,
                            30 => 4,
                            _ => 13,
                        };
                        None
                    }
                    a => unreachable!("segment: no action {a}"),
                };
                if let Some(finish) = finish {
                    return Ok(finish_token(data, finish, start_pos, end_pos));
                }
                label = Label::Again;
            }
            Label::Again => {
                // The state's to-state and from-state actions only reset and set the scanner's token start (ts),
                // which nothing reads.
                p += 1;
                label = if p != pe {
                    Label::Resume
                } else {
                    Label::TestEof
                };
            }
            Label::TestEof => {
                // The only end-of-input action (24) sets startPos, which nothing reads afterwards.
                if p == eof && S_EOF_TRANS[cs] > 0 {
                    label = Label::EofTrans(S_EOF_TRANS[cs] as usize - 1);
                    continue;
                }
                break;
            }
        }
    }
    if cs < S_FIRST_FINAL {
        return Err(PARSE_ERROR);
    }
    Ok(None)
}

/// The finish actions of segment_words.rl with `atEOF` set and one token wanted: the token, or none when the
/// rune after a checked token is invalid.
fn finish_token(data: &[u8], finish: Finish, start_pos: isize, end_pos: isize) -> Option<Found> {
    let (start, mut end) = (start_pos as usize, end_pos as usize);
    let typ = match finish {
        Finish::Number => return Some(found(start, end, SegmentType::Number)),
        Finish::Word => return Some(found(start, end, SegmentType::Letter)),
        Finish::Hangul => SegmentType::Letter,
        Finish::Ideo => SegmentType::Ideo,
        Finish::None => {
            let mut last = start;
            while last <= end {
                last += go_utf8::decode_rune(&data[last..]).1;
            }
            end = last - 1;
            SegmentType::None
        }
    };
    if go_utf8::decode_rune(&data[end + 1..]) == (go_utf8::RUNE_ERROR, 1) {
        return None;
    }
    Some(found(start, end, typ))
}

fn found(start: usize, end: usize, typ: SegmentType) -> Found {
    Found {
        start,
        end: end + 1,
        advance: end + 1,
        typ,
    }
}
